{"path": "/tmp/sv-25a6080b0c114d05891e33c0553f2d7b/Components/Pages/Board/KanbanBoard.razor", "file_text": "@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<div class="kanban-board">
    <h1>Project Board</h1>

    @if (isLoading)
    {
        <p class="loading-message">Loading tasks...</p>
    }
    else if (errorMessage is not null)
    {
        <div class="error-message">
            <p>@errorMessage</p>
            <button @onclick="LoadTasks">Retry</button>
        </div>
    }
    else
    {
        <BoardStats Tasks="allTasks" />
        <BoardSearchBar SearchText="@searchText" SearchTextChanged="HandleSearchChanged" />

        <div class="kanban-columns">
            <KanbanColumn ColumnName="To Do"
                          Tasks="GetFilteredTasks("To Do")"
                          ShowMoveLeft="false"
                          ShowMoveRight="true"
                          OnMoveRight="HandleMoveRight"
                          OnAddTask="args => HandleAddTask("To Do", args)" />

            <KanbanColumn ColumnName="In Progress"
                          Tasks="GetFilteredTasks("In Progress")"
                          ShowMoveLeft="true"
                          ShowMoveRight="true"
                          OnMoveLeft="HandleMoveLeft"
                          OnMoveRight="HandleMoveRight"
                          OnAddTask="args => HandleAddTask("In Progress", args)" />

            <KanbanColumn ColumnName="Done"
                          Tasks="GetFilteredTasks("Done")"
                          ShowMoveLeft="true"
                          ShowMoveRight="false"
                          OnMoveLeft="HandleMoveLeft"
                          OnAddTask="args => HandleAddTask("Done", args)" />
        </div>
    }
</div>

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly string[] Statuses = { "To Do", "In Progress", "Done" };

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private void HandleSearchChanged(string value)
    {
        searchText = value;
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var tasks = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return tasks.ToList();
    }

    private async Task HandleMoveLeft(TaskItem task)
    {
        var currentIndex = Array.IndexOf(Statuses, task.Status);
        if (currentIndex > 0)
        {
            var newStatus = Statuses[currentIndex - 1];
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            allTasks = allTasks.Select(t => t.Id == task.Id ? task with { Status = newStatus } : t).ToList();
        }
    }

    private async Task HandleMoveRight(TaskItem task)
    {
        var currentIndex = Array.IndexOf(Statuses, task.Status);
        if (currentIndex < Statuses.Length - 1)
        {
            var newStatus = Statuses[currentIndex + 1];
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            allTasks = allTasks.Select(t => t.Id == task.Id ? task with { Status = newStatus } : t).ToList();
        }
    }

    private async Task HandleAddTask(string status, (string Title, string Assignee, string Priority, DateTime DueDate) args)
    {
        var newTask = await TaskService.CreateTaskAsync(args.Title, args.Assignee, args.Priority, args.DueDate);
        allTasks.Add(newTask);
    }
}
"}

